const listUserTenants = `-- name: ListUserTenants :many
SELECT t.id, t.code, t.name, tm.status, tm.joined_at
FROM iam.tenant_members tm
JOIN iam.tenants t ON t.id = tm.tenant_id AND t.deleted_at IS NULL
WHERE tm.user_id = $1 AND tm.status = 'active'
ORDER BY t.name, t.id
`

type ListUserTenantsRow struct {
	ID       uuid.UUID          `json:"id"`
	Code     string             `json:"code"`
	Name     string             `json:"name"`
	Status   string             `json:"status"`
	JoinedAt pgtype.Timestamptz `json:"joined_at"`
}

func (q *Queries) ListUserTenants(ctx context.Context, userID uuid.UUID) ([]ListUserTenantsRow, error) {
	rows, err := q.db.Query(ctx, listUserTenants, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListUserTenantsRow{}
	for rows.Next() {
		var i ListUserTenantsRow
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.Name,
			&i.Status,
			&i.JoinedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockPasswordResetChallenge = `-- name: LockPasswordResetChallenge :one
SELECT id, user_id
FROM iam.verification_challenges
WHERE secret_hash = $1
  AND challenge_type = 'password_reset'
  AND consumed_at IS NULL
  AND expires_at > now()
  AND attempts < max_attempts
FOR UPDATE
`

type LockPasswordResetChallengeRow struct {
	ID     uuid.UUID  `json:"id"`
	UserID *uuid.UUID `json:"user_id"`
}

func (q *Queries) LockPasswordResetChallenge(ctx context.Context, secretHash []byte) (LockPasswordResetChallengeRow, error) {
	row := q.db.QueryRow(ctx, lockPasswordResetChallenge, secretHash)
	var i LockPasswordResetChallengeRow
	err := row.Scan(&i.ID, &i.UserID)
	return i, err
}

const revokeAllUserRefreshTokens = `-- name: RevokeAllUserRefreshTokens :exec
UPDATE iam.refresh_tokens
SET revoked_at = COALESCE(revoked_at, now())
WHERE revoked_at IS NULL
  AND session_id IN (SELECT id FROM iam.sessions WHERE user_id = $1)
`

func (q *Queries) RevokeAllUserRefreshTokens(ctx context.Context, userID uuid.UUID) error {
	_, err := q.db.Exec(ctx, revokeAllUserRefreshTokens, userID)
	return err
}

const revokeAllUserSessions = `-- name: RevokeAllUserSessions :execrows
UPDATE iam.sessions
SET status = 'revoked',
    revoked_at = COALESCE(revoked_at, now()),
    revoke_reason = 'password_reset',
    access_token_version = access_token_version + 1
WHERE user_id = $1
  AND status = 'active'
  AND revoked_at IS NULL
`

func (q *Queries) RevokeAllUserSessions(ctx context.Context, userID uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, revokeAllUserSessions, userID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const revokeOtherSessionRefreshTokens = `-- name: RevokeOtherSessionRefreshTokens :exec
UPDATE iam.refresh_tokens
SET revoked_at = COALESCE(revoked_at, now())
WHERE revoked_at IS NULL
  AND session_id IN (
    SELECT s.id FROM iam.sessions AS s
    WHERE s.user_id = $1 AND s.id <> $2
  )
`

