const updatePasswordAfterReset = `-- name: UpdatePasswordAfterReset :one
UPDATE iam.user_credentials
SET password_hash = $1,
    password_algorithm = 'argon2id',
    password_version = password_version + 1,
    password_changed_at = now(),
    force_password_change = false,
    failed_attempts = 0,
    locked_until = NULL
WHERE user_id = $2
  AND password_hash = $3
  AND password_version = $4
RETURNING password_version
`

