const updateSelfProfile = `-- name: UpdateSelfProfile :one
UPDATE iam.users
SET display_name = COALESCE($1::varchar, display_name),
    locale = COALESCE($2::varchar, locale),
    time_zone = COALESCE($3::varchar, time_zone)
WHERE id = $4 AND deleted_at IS NULL AND status = 'active'
RETURNING id, username, email, mobile, display_name, real_name, avatar_file_id, gender, birthday, bio, locale, time_zone, status, email_verified_at, mobile_verified_at, last_login_at, last_active_at, lock_version, is_system, metadata, created_at, updated_at, deleted_at
`

type UpdateSelfProfileParams struct {
	DisplayName *string   `json:"display_name"`
	Locale      *string   `json:"locale"`
	TimeZone    *string   `json:"time_zone"`
	ID          uuid.UUID `json:"id"`
}

func (q *Queries) UpdateSelfProfile(ctx context.Context, arg UpdateSelfProfileParams) (IamUser, error) {
	row := q.db.QueryRow(ctx, updateSelfProfile,
		arg.DisplayName,
		arg.Locale,
		arg.TimeZone,
		arg.ID,
	)
	var i IamUser
	err := row.Scan(
		&i.ID,
		&i.Username,
		&i.Email,
		&i.Mobile,
		&i.DisplayName,
		&i.RealName,
		&i.AvatarFileID,
		&i.Gender,
		&i.Birthday,
		&i.Bio,
		&i.Locale,
		&i.TimeZone,
		&i.Status,
		&i.EmailVerifiedAt,
		&i.MobileVerifiedAt,
		&i.LastLoginAt,
		&i.LastActiveAt,
		&i.LockVersion,
		&i.IsSystem,
		&i.Metadata,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}
